<script setup>import {Head,Link,useForm,usePage} from '@inertiajs/vue3';import {computed,ref} from 'vue';import TurnstileWidget from '../../Components/TurnstileWidget.vue';import CustomerShell from '../../Components/CustomerShell.vue';const page=usePage(),turnstile=ref(null),security=computed(()=>page.props.security||{}),form=useForm({email:'',password:'',remember:false,turnstile_token:''});const submit=()=>form.post('/login',{onFinish:()=>{form.reset('password');turnstile.value?.reset()}});</script>
<template><Head title="Masuk"/><CustomerShell compact-footer><main class="lf-auth-wrap"><form class="lf-auth-card" @submit.prevent="submit"><p class="lf-eyebrow">Selamat datang</p><h1>Masuk LFAMILIA</h1><p>Masuk untuk melihat saldo, pesanan, membership, tiket, dan profilmu.</p><div class="grid gap-3"><label class="text-[10px] font-semibold text-white/70">Email<input v-model="form.email" type="email" required></label><label class="text-[10px] font-semibold text-white/70">Kata sandi<input v-model="form.password" type="password" required></label><TurnstileWidget v-if="security.turnstile_required" ref="turnstile" :site-key="security.turnstile_site_key" :action="security.turnstile_action" @token="form.turnstile_token=$event"/><button class="lf-primary w-full" :disabled="form.processing">Masuk</button><a href="/auth/google/redirect" class="lf-secondary w-full">Masuk dengan Google</a></div><div class="lf-auth-links"><Link href="/forgot-password">Lupa password?</Link><Link href="/register">Daftar</Link></div></form></main></CustomerShell></template>